import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.C-si7TFR.js";const u=JSON.parse('{"title":"安装与部署","description":"","frontmatter":{"title":"安装与部署"},"headers":[],"relativePath":"zh/guide/deployment.md","filePath":"zh/guide/deployment.md"}'),r={name:"zh/guide/deployment.md"};function o(n,e,d,h,s,c){return l(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="安装与部署" tabindex="-1">安装与部署 <a class="header-anchor" href="#安装与部署" aria-label="Permalink to &quot;安装与部署&quot;">​</a></h1><h2 id="选择安装包" tabindex="-1">选择安装包 <a class="header-anchor" href="#选择安装包" aria-label="Permalink to &quot;选择安装包&quot;">​</a></h2><p>从<a href="https://iolinker.com/#cta" target="_blank" rel="noreferrer">官网统一下载区</a>选择操作系统和架构。官网 <code>version.json</code> 是唯一的版本与安装包地址来源；文档不维护另一份下载列表。</p><p>当前指南按源码界面核对，不代表版本文件中的每个安装包都具备全部能力。外部安装包的在线可用性需要在发布前另行验证。</p><h2 id="启动与安全初始化" tabindex="-1">启动与安全初始化 <a class="header-anchor" href="#启动与安全初始化" aria-label="Permalink to &quot;启动与安全初始化&quot;">​</a></h2><ol><li>在受控环境解压并启动程序，查看实际启动日志与本地访问地址。</li><li>端口、数据目录、HTTPS 和监听地址以当前版本实际配置为准，不照搬旧教程中的参数。</li><li>首次登录后立即修改初始密码，并完成账户安全配置。</li><li>在确认身份验证、访问控制和备份前，不要开放公网或不受信网络访问。</li></ol><p>旧启动文章仅作历史参考。文档不会提供固定默认密码，也不会把“程序启动”视为“可以安全暴露到公网”。</p><h2 id="外部依赖" tabindex="-1">外部依赖 <a class="header-anchor" href="#外部依赖" aria-label="Permalink to &quot;外部依赖&quot;">​</a></h2><p>IOLinker 的本地部署不代表所有依赖都在本地：</p><ul><li>模型、Embedding、搜索、MCP 和其他外部服务可能需要网络、凭证与独立账号。</li><li>提示词、检索片段、工具参数和业务数据可能按你的配置发送给外部服务。</li><li>Python、Lua 等脚本运行环境和第三方命令需在目标环境中核实，不能把“有脚本节点”当作所有运行时已安装。</li><li>模型或网络故障可能导致任务等待、失败或诊断不可用。</li></ul><h2 id="工具与远程访问安全" tabindex="-1">工具与远程访问安全 <a class="header-anchor" href="#工具与远程访问安全" aria-label="Permalink to &quot;工具与远程访问安全&quot;">​</a></h2><ul><li>将文件和命令工具限制在明确的工作目录，使用最小权限账户运行。</li><li>外部 HTTP、数据库与 SSH 操作使用受控目标和参数绑定，禁止把用户输入直接拼接为命令或 SQL。</li><li>MCP STDIO 只运行经过审查的程序；外部服务优先 HTTPS，并按部署策略限制内部地址访问。</li><li>企微遥控配置用户白名单，Secret 泄露后在服务商平台轮换。</li><li>分享配置、截图、执行记录和链路前，移除令牌、个人信息及真实业务数据。</li></ul><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><p>本指南不承诺微系统／通用业务页面搭建、无限层级子 Agent、全渠道一键接入、行字段级权限或无条件性能指标。当前可见的 Agent、工作流、数据表、表单和工具配置请按各篇前提使用。</p>',14)])])}const _=a(r,[["render",o]]);export{u as __pageData,_ as default};
